<script lang="ts">
  import { onMount } from 'svelte'; import type { Collection, Track, View } from './types/music'; import type { NativeQueueTrack, PlayerSnapshot } from './types/player'; import type { Playlist, PlaylistDetails, PlaylistSortMode } from './types/playlist'; import { collections as initialCollections, tracks as initialTracks } from './data/mock'; import { libraryService } from './services/libraryService'; import { playlistService } from './services/playlistService'; import { playerService, shouldInitializeQueue } from './services/playerService'; import { stableHue, toUiTrack } from './services/trackMapper'; import { albumCollections, artistCollections, sortPlaylists, type PlaylistListSort } from './services/libraryCollections'; import { fallbackView } from './services/navigation';
  import HomeScreen from './screens/HomeScreen.svelte'; import SearchScreen from './screens/SearchScreen.svelte'; import LibraryScreen from './screens/LibraryScreen.svelte'; import LibraryCollectionScreen from './screens/LibraryCollectionScreen.svelte'; import SettingsScreen from './screens/SettingsScreen.svelte'; import PlayerScreen from './screens/PlayerScreen.svelte'; import PlaylistScreen from './screens/PlaylistScreen.svelte'; import PlaylistAddScreen from './screens/PlaylistAddScreen.svelte'; import PlaylistEditScreen from './screens/PlaylistEditScreen.svelte'; import DownloadScreen from './screens/DownloadScreen.svelte'; import MiniPlayer from './components/MiniPlayer.svelte'; import BottomNavigation from './components/BottomNavigation.svelte'; import TrackActions from './components/TrackActions.svelte';
  let view: View = 'home'; let historyDepth = 0; let historyReady = false; let tracks = initialTracks; let current = tracks[0]; let playing = false; let position = 0; let nativeLibrary = false; let nativePlayer = false; let playerState: PlayerSnapshot | null = null; let activePlaylistId: string | null = null; let recordedPlaybackId: string | null = null; let actionTrack: Track | null = null; let actionFromPlaylist = false; let playlists: Playlist[] = []; let playlistDetails: PlaylistDetails | null = null; let activeLibraryCollection: Collection | null = null; let importingBundle = false; let playlistSort: PlaylistListSort = 'recent';
  $: displayedPlaylists = nativeLibrary && playlistSort === 'recent' ? playlists : sortPlaylists(playlists, playlistSort);
  $: collections = nativeLibrary ? [...displayedPlaylists.map(toCollection), ...albumCollections(tracks), ...artistCollections(tracks)] : [...initialCollections, ...albumCollections(tracks), ...artistCollections(tracks)];
  $: navigationView = view === 'playlist' || view === 'playlist-add' || view === 'playlist-edit' || view === 'library-collection' || view === 'downloads' ? 'library' : view;
  onMount(() => {
    let active = true;
    const savedSort = localStorage.getItem('rigbyfy.playlist-sort');
    if (savedSort === 'recent' || savedSort === 'name-ascending' || savedSort === 'name-descending') playlistSort = savedSort;
    history.replaceState({ rigbyfy: true, view: 'home', depth: 0 }, ''); historyReady = true;
    const onPopState = (event: PopStateEvent) => { const entry = event.state as { rigbyfy?: boolean; view?: View; depth?: number } | null; if (!entry?.rigbyfy || !entry.view) return; view = entry.view; historyDepth = Math.max(0, entry.depth ?? 0); };
    window.addEventListener('popstate', onPopState);
    void (async () => { try { const [stored, savedPlaylists] = await Promise.all([libraryService.listTracks(), playlistService.list()]); if (!active) return; nativeLibrary = true; playlists = savedPlaylists; if (stored.length > 0) { tracks = stored.map(toUiTrack); current = tracks[0]; } } catch { nativeLibrary = false; } })();
    const timer = window.setInterval(() => { if (nativePlayer) { void playerService.getState().then(syncPlayer).catch(() => { nativePlayer = false; }); } else if (playing) { position = Math.min(position + 1, current.duration); if (position >= current.duration) playing = false; } }, 1_000);
    return () => { active = false; window.clearInterval(timer); window.removeEventListener('popstate', onPopState); };
  });
  function navigate(next: View) { if (next === 'home') { if (historyReady && historyDepth > 0) { view = 'home'; history.go(-historyDepth); } else view = 'home'; return; } if (next === view) return; historyDepth += 1; history.pushState({ rigbyfy: true, view: next, depth: historyDepth }, ''); view = next; if (next === 'library' && nativeLibrary) { void refreshLibrary(); void refreshPlaylists(); } }
  function replaceView(next: View) { history.replaceState({ rigbyfy: true, view: next, depth: historyDepth }, ''); view = next; }
  function navigateBack(fallback: View = 'home') { if (historyReady && historyDepth > 0) history.back(); else replaceView(fallbackView(view) ?? fallback); }
  function openSettings() { navigate('settings'); }
  function openPlayer() { navigate('player'); }
  function toCollection(playlist: Playlist): Collection { return { id: playlist.id, title: playlist.name, subtitle: `${playlist.trackCount} músicas`, hue: stableHue(playlist.id), type: 'playlist' }; }
  function nativeQueue(source: Track[] = tracks): NativeQueueTrack[] { return source.filter((track): track is Track & { sourceUri: string } => Boolean(track.sourceUri)).map(({ id, sourceUri, title, artist, album, artworkUri }) => ({ id, sourceUri, title, artist, album, artworkUri })); }
  function syncPlayer(state: PlayerSnapshot) { nativePlayer = true; playerState = state; playing = state.isPlaying; position = Math.round(state.positionMs / 1_000); const selected = tracks.find((track) => track.id === state.currentTrackId); if (selected) current = selected; if (nativeLibrary && state.isPlaying && state.currentTrackId && state.currentTrackId !== recordedPlaybackId) { recordedPlaybackId = state.currentTrackId; void libraryService.recordPlayback(state.currentTrackId, activePlaylistId).catch(() => { if (recordedPlaybackId === state.currentTrackId) recordedPlaybackId = null; }); } }
  async function play(track: Track, source: Track[] = tracks, playlistId: string | null = null) { activePlaylistId = playlistId; recordedPlaybackId = null; current = track; position = 0; const queue = nativeQueue(source); const index = queue.findIndex((item) => item.id === track.id); if (index < 0) { playing = true; return; } try { syncPlayer(await playerService.setQueue(queue, index)); syncPlayer(await playerService.play()); } catch { nativePlayer = false; playing = false; } }
  async function toggle() { if (!current.sourceUri) { playing = !playing; return; } try { if (playing) { syncPlayer(await playerService.pause()); return; } if (shouldInitializeQueue(playerState, current.id)) { const queue = nativeQueue(); const index = queue.findIndex((item) => item.id === current.id); if (index < 0) return; syncPlayer(await playerService.setQueue(queue, index)); } syncPlayer(await playerService.play()); } catch { nativePlayer = false; playerState = null; } }
  async function step(direction: number) { if (nativePlayer) { try { syncPlayer(direction > 0 ? await playerService.skipNext() : await playerService.skipPrevious()); return; } catch { nativePlayer = false; } } const index = tracks.findIndex((track) => track.id === current.id); current = tracks[(index + direction + tracks.length) % tracks.length]; playing = true; }
  async function seek(seconds: number) { position = seconds; if (nativePlayer) { try { syncPlayer(await playerService.seekTo(seconds * 1_000)); } catch { nativePlayer = false; } } }
  async function importFromDevice() { try { const imported = await libraryService.importFromDevice(); if (imported.length > 0) { const stored = await libraryService.listTracks(); tracks = stored.map(toUiTrack); current = toUiTrack(imported[0]); nativeLibrary = true; navigate('library'); } } catch { nativeLibrary = false; } }
  async function importBundle() {
    if (importingBundle) return;
    importingBundle = true;
    try {
      const result = await libraryService.importBundle();
      await refreshLibrary(); await refreshPlaylists(); navigate('library');
      alert(`${result.importedTracks} músicas importadas e ${result.playlistsUpdated} playlists atualizadas.${result.missingFiles ? ` ${result.missingFiles} arquivo(s) não foram encontrados.` : ''}`);
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Não foi possível importar o bundle.';
      alert(message);
      console.error('Falha ao importar bundle', error);
    } finally {
      importingBundle = false;
    }
  }
  async function favorite(track: Track) { const favorite = !track.favorite; tracks = tracks.map((item) => item.id === track.id ? { ...item, favorite } : item); current = tracks.find((item) => item.id === current.id) ?? current; if (nativeLibrary) { try { await libraryService.setFavorite(track.id, favorite); } catch { tracks = tracks.map((item) => item.id === track.id ? { ...item, favorite: !favorite } : item); current = tracks.find((item) => item.id === current.id) ?? current; } } }
  async function editMetadata(track: Track, values: { title: string; artist: string; album: string }) { if (!nativeLibrary) throw new Error('Edição disponível para músicas importadas.'); const updated = toUiTrack(await libraryService.updateMetadata(track.id, { title: values.title, artist: values.artist || undefined, album: values.album || undefined })); tracks = tracks.map((item) => item.id === track.id ? updated : item); if (current.id === track.id) current = updated; }
  async function refreshPlaylists() { playlists = await playlistService.list(); }
  async function refreshLibrary() { const stored = await libraryService.listTracks(); tracks = stored.map(toUiTrack); nativeLibrary = true; }
  async function addToPlaylist(track: Track, playlist: Collection) { if (!nativeLibrary) throw new Error('Playlists disponíveis para músicas importadas.'); await playlistService.addTracks(playlist.id, [track.id]); await refreshPlaylists(); if (playlistDetails?.id === playlist.id) playlistDetails = await playlistService.get(playlist.id); }
  async function createPlaylist() { const name = prompt('Nome da nova playlist'); if (!name?.trim()) return; const created = await playlistService.create(name); await refreshPlaylists(); await openPlaylist(toCollection(created)); }
  async function openPlaylist(item: Collection) { if (!playlists.some(playlist => playlist.id === item.id)) return; playlistDetails = await playlistService.get(item.id); navigate('playlist'); }
  function openLibraryCollection(item: Collection) { activeLibraryCollection = item; navigate('library-collection'); }
  function activeCollectionTracks(): Track[] { const ids = new Set(activeLibraryCollection?.trackIds ?? []); return tracks.filter((track) => ids.has(track.id)); }
  function setPlaylistSort(sort: PlaylistListSort) { playlistSort = sort; localStorage.setItem('rigbyfy.playlist-sort', sort); if (nativeLibrary) void refreshPlaylists(); }
  function playlistTracks(): Track[] { return playlistDetails?.tracks.map(toUiTrack) ?? []; }
  async function syncActivePlaylistQueue() { if (!playlistDetails || !playerState?.currentTrackId) return; const queue = playlistTracks(); let index = queue.findIndex(track => track.id === playerState?.currentTrackId); if (index < 0) index = 0; if (!queue[index]) { syncPlayer(await playerService.stop()); return; } const wasPlaying = playing; syncPlayer(await playerService.setQueue(nativeQueue(queue), index, index === queue.findIndex(track => track.id === current.id) ? position * 1000 : 0)); if (wasPlaying) syncPlayer(await playerService.play()); }
  async function sortPlaylist(mode: PlaylistSortMode) { if (!playlistDetails) return; playlistDetails = await playlistService.setSort(playlistDetails.id, mode, mode === 'recently_added' ? 'descending' : 'ascending'); await refreshPlaylists(); await syncActivePlaylistQueue(); }
  async function updatePlaylistDetails(name: string, description: string) { if (!playlistDetails) return; await playlistService.update(playlistDetails.id, { name, description: description || undefined, artworkUri: playlistDetails.artworkUri ?? undefined, expectedVersion: playlistDetails.version }); playlistDetails = await playlistService.get(playlistDetails.id); await refreshPlaylists(); }
  async function deleteCurrentPlaylist() { if (!playlistDetails) return; await playlistService.delete(playlistDetails.id); playlistDetails = null; await refreshPlaylists(); replaceView('library'); }
  async function duplicateCurrentPlaylist() { if (!playlistDetails) return; const copy = await playlistService.create(`${playlistDetails.name} (cópia)`); if (playlistDetails.tracks.length) await playlistService.addTracks(copy.id, playlistDetails.tracks.map(track => track.id)); await refreshPlaylists(); }
  async function clearCurrentPlaylist() { if (!playlistDetails) return; playlistDetails = await playlistService.replaceOrder(playlistDetails.id, [], playlistDetails.version); await refreshPlaylists(); await syncActivePlaylistQueue(); }
  function playPlaylistTrack(track: Track, source: Track[]) { void play(track, source, playlistDetails?.id ?? null); }
  function shufflePlaylist(source: Track[]) { const shuffled = [...source]; for (let index=shuffled.length-1;index>0;index--){const target=Math.floor(Math.random()*(index+1));[shuffled[index],shuffled[target]]=[shuffled[target],shuffled[index]];} if(shuffled[0]) void play(shuffled[0],shuffled,playlistDetails?.id ?? null); }
  async function addSelectedTracks(ids: string[]) { if (!playlistDetails) return; playlistDetails = await playlistService.addTracks(playlistDetails.id, ids); await refreshPlaylists(); }
  async function savePlaylistOrder(ids: string[]) { if (!playlistDetails) return; playlistDetails = await playlistService.replaceOrder(playlistDetails.id, ids, playlistDetails.version); await refreshPlaylists(); await syncActivePlaylistQueue(); navigateBack('playlist'); }
  async function removeFromPlaylist(track: Track) { if (!playlistDetails) return; const ids = playlistDetails.tracks.filter(item => item.id !== track.id).map(item => item.id); playlistDetails = await playlistService.replaceOrder(playlistDetails.id, ids, playlistDetails.version); await refreshPlaylists(); await syncActivePlaylistQueue(); }
  async function removeFromLibrary(track: Track) { if (!nativeLibrary) throw new Error('Remoção disponível para músicas importadas.'); await libraryService.removeTrack(track.id); const remaining = tracks.filter((item) => item.id !== track.id); tracks = remaining; if (current.id === track.id) { if (nativePlayer) { try { syncPlayer(await playerService.stop()); } catch { nativePlayer = false; } } current = remaining[0] ?? initialTracks[0]; position = 0; playing = false; } }
</script>

{#if view === 'player'}<PlayerScreen track={current} {playing} {position} onback={() => navigateBack()} ontoggle={toggle} onnext={() => step(1)} onprevious={() => step(-1)} onseek={seek} onfavorite={favorite} onmore={(track) => actionTrack = track} />
{:else if view === 'playlist' && playlistDetails}<PlaylistScreen playlist={playlistDetails} {current} {playing} active={activePlaylistId === playlistDetails.id} onback={() => navigateBack('library')} onplay={playPlaylistTrack} ontoggle={toggle} onshuffle={shufflePlaylist} onadd={() => navigate('playlist-add')} onedit={() => navigate('playlist-edit')} onmore={(track)=>{actionFromPlaylist=true;actionTrack=track;}} onfavorite={favorite} onsort={sortPlaylist} ondetails={updatePlaylistDetails} ondelete={deleteCurrentPlaylist} onduplicate={duplicateCurrentPlaylist} onclear={clearCurrentPlaylist} />
{:else if view === 'playlist-add' && playlistDetails}<PlaylistAddScreen name={playlistDetails.name} {tracks} existingIds={playlistDetails.tracks.map(track=>track.id)} onback={()=>navigateBack('playlist')} onadd={addSelectedTracks} ondone={()=>navigateBack('playlist')} />
{:else if view === 'playlist-edit' && playlistDetails}<PlaylistEditScreen name={playlistDetails.name} initialTracks={playlistTracks()} onback={()=>navigateBack('playlist')} onsave={savePlaylistOrder} onadd={()=>navigate('playlist-add')} />
{:else if view === 'library-collection' && activeLibraryCollection}<LibraryCollectionScreen collection={activeLibraryCollection} tracks={activeCollectionTracks()} {current} onback={() => navigateBack('library')} onplay={(track, source) => play(track, source)} onfavorite={favorite} onmore={(track) => actionTrack = track} />
{:else if view === 'downloads'}<DownloadScreen onback={() => navigateBack()} onimported={refreshLibrary} />
{:else}<div class="app-shell">{#if view === 'home'}<HomeScreen {tracks} {collections} {current} onplay={play} onfavorite={favorite} onmore={(track) => actionTrack = track} onsettings={openSettings} onadd={importFromDevice} ondownload={() => navigate('downloads')} oncollection={openPlaylist} />{:else if view === 'search'}<SearchScreen {tracks} {current} onplay={play} onfavorite={favorite} onmore={(track) => actionTrack = track} onsettings={openSettings} ondownload={() => navigate('downloads')} />{:else if view === 'library'}<LibraryScreen {tracks} {collections} {current} onplay={play} onfavorite={favorite} onmore={(track) => actionTrack = track} onplaylist={openPlaylist} oncollection={openLibraryCollection} oncreateplaylist={createPlaylist} onsettings={openSettings} onadd={importFromDevice} onimportbundle={importBundle} importingbundle={importingBundle} {playlistSort} onplaylistsort={setPlaylistSort} />{:else}<SettingsScreen onback={() => navigateBack()} />{/if}</div>
{/if}
{#if view !== 'player'}<MiniPlayer track={current} {playing} {position} duration={playerState?.durationMs ? playerState.durationMs / 1_000 : current.duration} onopen={openPlayer} ontoggle={toggle} /><BottomNavigation active={navigationView} {navigate} />{/if}
{#if actionTrack}<TrackActions track={actionTrack} {collections} onclose={() => { actionTrack = null; actionFromPlaylist = false; }} onfavorite={favorite} onremove={removeFromLibrary} onremovefromplaylist={actionFromPlaylist ? removeFromPlaylist : undefined} onedit={editMetadata} onplaylist={addToPlaylist} />{/if}
